import networkx as nx
from itertools import combinations

def solve_max_k(n):
    # Build King's graph
    G = nx.Graph()
    for r in range(n):
        for c in range(n):
            G.add_node((r, c))

    for r in range(n):
        for c in range(n):
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        G.add_edge((r, c), (nr, nc))

    # We want to find the maximum size of a set S such that the induced subgraph G[S] has max degree 1.
    # This is a maximum weight independent set problem if we rethink it, but let's use brute force for small n.
    import itertools

    nodes = list(G.nodes())
    max_k = 0
    for k in range(n * n, 0, -1):
        for S in combinations(nodes, k):
            subgraph = G.subgraph(S)
            if all(deg <= 1 for node, deg in subgraph.degree()):
                return k
    return 0

for n in range(1, 5):
    print(f"n={n}, max_k={solve_max_k(n)}")

