from itertools import combinations

def solve_max_k(n):
    G = nx.Graph()
    for r in range(n):
        for c in range(n):
            G.add_node((r, c))
    for r in range(n):
        for c in range(n):
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        G.add_edge((r, c), (nr, nc))

    import itertools
    nodes = list(G.nodes())

    # Instead of combinations, let's use a more efficient way to find the max size.
    # This is equivalent to finding the maximum size of a 1-dependent set.
    # We can use a simple backtracking with pruning.

    best_S = []

    def is_valid(S, node):
        # Check if adding 'node' to S keeps max degree <= 1
        # Neighbors of 'node' in S
        neighbors_in_S = [n for n in G.neighbors(node) if n in S]
        if len(neighbors_in_S) > 1:
            return False
        if len(neighbors_in_S) == 1:
            # The neighbor must have degree 0 in S
            neighbor = neighbors_in_S[0]
            if any(n in S for n in G.neighbors(neighbor) if n != node):
                return False
        return True

    def backtrack(candidates, current_S):
        nonlocal best_S
        if not candidates:
            if len(current_S) > len(best_S):
                best_S = list(current_S)
            return

        if len(current_S) + len(candidates) <= len(best_S):
            return

        v = candidates[0]
        # Option 1: v is in S
        if is_valid(current_S, v):
            backtrack(candidates[1:], current_S | {v})
        # Option 2: v is not in S
        backtrack(candidates[1:], current_S)

    backtrack(nodes, set())
    return len(best_S)

